    bytes32 private constant _RATE_LIMIT_STORAGE_LOCATION =
        0x5a044ec14f9996e1c7b3feb4fcac64ff4b38fefa34bc32f7dfd1713c9c25dc00;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      EVENTS / ERRORS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Emitted when an account's rate-limit configuration is set or updated.
